// render/spritedata_monsters.js â€” procedural pixel art for the entire bestiary.
//
// Every creature is authored as a small number of "views" (front / side / back)
// written as arrays of palette-key characters. The full 16-frame four-direction
// walk cycle, the hover bob, the ooze squash and the battle 'attack' / 'hurt'
// poses are all DERIVED from those views by pure string transforms. That is what
// lets 146 creature sprites live in one readable file while every one of them
// still exposes the exact frame names the actor compositor and BattleScene want:
//
//   'down-0'..'down-3'  'left-0'..'left-3'  'right-0'..'right-3'  'up-0'..'up-3'
//   (0 = contact/idle, 1 = left foot forward, 2 = right foot forward, 3 = idle bob)
//
// plus 'attack' and 'hurt' on every creature, and an `anims` block on floaters,
// oozes and incorporeal things. Side views are authored FACING LEFT; the right
// facing set is mirrored automatically.
//
// Palette keys (uniform across every monster sprite in this file):
//   K outline    Z black/pupil    W bone-white    T ivory / claw / teeth
//   1 2 3  primary material   (dark, mid, light)
//   4 5 6  secondary material (dark, mid, light)
//   7 8 9  tertiary / metal   (dark, mid, light)
//   R red   Y yellow   E eye-glow   G green   B blue   U purple   O orange
//
// Colours are literal hex so that the palette-swap tints in MONSTER_SPRITE_MAP
// (dire wolf = wolf shaded darker, orog = orc reddened) read predictably.

import { defineSprite, shadeHex, hasSprite, makeColorway } from './sprites.js';
import { ramp } from './palette.js';
import WYRM from './art/wyrm-sculpt.js';
import GOBLIN from './art/goblin-sculpt.js';
import ORC from './art/orc-sculpt.js';
import OGRE from './art/ogre-sculpt.js';
import SKELETON from './art/skeleton-sculpt.js';
import WOLF from './art/wolf-sculpt.js';

// ---------------------------------------------------------------------------
// palette construction
// ---------------------------------------------------------------------------

const RAMPS = [['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9']];

/**
 * Build a monster palette from up to three "mid" colours; the dark and light
 * tones of each material are derived so every sprite keeps one light direction
 * and 3 tones per material without the author picking nine hexes.
 */
function pal(a, b, c, extra) {
  const out = {
    K: '#0e0a09', Z: '#050405', W: '#efe6d2', T: '#ddd0ae',
    R: '#a82a2a', Y: '#e8c33a', E: '#ffd24a', G: '#5fd07a',
    B: '#5aa8ff', U: '#a86ad0', O: '#ff8c28',
  };
  const src = [a, b, c];
  for (let i = 0; i < 3; i++) {
    const hex = src[i];
    if (!hex) continue;
    const k = RAMPS[i];
    out[k[0]] = shadeHex(hex, -0.38);
    out[k[1]] = hex;
    out[k[2]] = shadeHex(hex, 0.26);
  }
  return extra ? Object.assign(out, extra) : out;
}

// ---------------------------------------------------------------------------
// row transforms â€” everything below operates on FITTED rows (exact w x h)
// ---------------------------------------------------------------------------

/** Pad/trim authored rows to exactly w x h so transforms are safe. */
function fit(rows, w, h) {
  const out = [];
  for (let y = 0; y < h; y++) {
    let r = rows && rows[y] != null ? String(rows[y]) : '';
    if (r.length < w) r += '.'.repeat(w - r.length);
    else if (r.length > w) r = r.slice(0, w);
    out.push(r);
  }
  return out;
}

/** Mirror horizontally (side view -> the other facing). */
function mirrorRows(rows) {
  return rows.map((r) => r.split('').reverse().join(''));
}

/**
 * Author only the left half of a bilaterally symmetric front/back view; the
 * right half is mirrored in. A half-row that stops short of the centre line is
 * extended with its own last colour rather than with transparency, so a row the
 * author left one character short never opens a seam down the creature's spine.
 * A row that deliberately ENDS in '.' keeps its gap (that is how legs part).
 */
function sym(half, w) {
  const hw = w >> 1;
  const out = [];
  for (let y = 0; y < half.length; y++) {
    let r = half[y] != null ? String(half[y]) : '';
    if (r.length > hw) r = r.slice(0, hw);
    else if (r.length < hw) {
      const last = r[r.length - 1];
      const fillCh = last && last !== '.' && last !== ' ' ? last : '.';
      r += fillCh.repeat(hw - r.length);
    }
    out.push(r + r.split('').reverse().join(''));
  }
  return out;
}

/** Character substitution â€” the cheap way to turn a front view into a back view. */
function sub(rows, map) {
  return rows.map((r) => r.replace(/./g, (ch) => (map[ch] !== undefined ? map[ch] : ch)));
}

/** Translate the whole sprite vertically (hover bob, ooze pulse). */
function shiftY(rows, dy) {
  const w = rows[0].length, h = rows.length, blank = '.'.repeat(w), out = [];
  for (let y = 0; y < h; y++) {
    const sy = y - dy;
    out.push(sy >= 0 && sy < h ? rows[sy] : blank);
  }
  return out;
}

/** Translate the whole sprite horizontally. */
function shiftX(rows, dx) {
  const w = rows[0].length;
  return rows.map((r) => {
    if (dx === 0) return r;
    return dx > 0 ? ('.'.repeat(dx) + r).slice(0, w) : (r.slice(-dx) + '.'.repeat(-dx));
  });
}

/**
 * Raise one foot: inside the leg region, one half of the sprite is pulled up a
 * pixel so the sole leaves the ground. half 0 = the sprite's left, 1 = right.
 * This is the whole walk cycle â€” at 16px a one-pixel foot lift reads perfectly.
 */
function liftFoot(rows, legTop, half) {
  const h = rows.length, w = rows[0].length, mid = w / 2, blank = '.'.repeat(w);
  const out = rows.slice();
  for (let y = Math.max(0, legTop); y < h; y++) {
    const cur = rows[y], nxt = y + 1 < h ? rows[y + 1] : blank;
    let r = '';
    for (let x = 0; x < w; x++) r += ((half === 0) === (x < mid)) ? nxt[x] : cur[x];
    out[y] = r;
  }
  return out;
}

/** Second idle frame: the body settles a pixel while the feet stay planted. */
function bob(rows, legTop) {
  const out = rows.slice(), w = rows[0].length;
  const top = Math.min(legTop, rows.length);
  for (let y = top - 1; y >= 1; y--) out[y] = rows[y - 1];
  out[0] = '.'.repeat(w);
  return out;
}

/** Battle 'attack': the body rears up over planted feet. */
function rise(rows, legTop) {
  const out = rows.slice();
  const top = Math.min(legTop, rows.length);
  for (let y = 0; y < top - 1; y++) out[y] = rows[y + 1];
  return out;
}

/** Battle 'hurt': the body recoils back and to the side. */
function flinch(rows, legTop) {
  const out = rows.slice(), w = rows[0].length;
  const top = Math.min(legTop, rows.length);
  for (let y = 0; y < top; y++) out[y] = ('.' + rows[y]).slice(0, w);
  return out;
}

/** Ooze pulse: mass sags while the base stays put. */
function squash(rows) {
  const s = shiftY(rows, 1);
  s[rows.length - 1] = rows[rows.length - 1];
  return s;
}

/** Ooze pulse: mass rears while the base stays put. */
function stretch(rows) {
  const s = shiftY(rows, -1);
  s[rows.length - 1] = rows[rows.length - 1];
  return s;
}

// ---------------------------------------------------------------------------
// sprite builders â€” each pushes a finished defineSprite() payload
// ---------------------------------------------------------------------------

const DEFS = [];
const DEF_INDEX = new Map();

function push(name, def) {
  DEFS.push({ name, def });
  DEF_INDEX.set(name, def);
  return name;
}

const WALK_ANIMS = {
  walkDown: { frames: ['down-0', 'down-1', 'down-0', 'down-2'], fps: 8 },
  walkLeft: { frames: ['left-0', 'left-1', 'left-0', 'left-2'], fps: 8 },
  walkRight: { frames: ['right-0', 'right-1', 'right-0', 'right-2'], fps: 8 },
  walkUp: { frames: ['up-0', 'up-1', 'up-0', 'up-2'], fps: 8 },
  idle: { frames: ['down-0', 'down-3'], fps: 2 },
  attack: { frames: ['attack', 'down-0'], fps: 6, loop: false },
};

const FLOAT_ANIMS = {
  float: { frames: ['f0', 'f1', 'f2', 'f1'], fps: 6 },
  idle: { frames: ['f0', 'f1', 'f2', 'f1'], fps: 6 },
  walkDown: { frames: ['down-0', 'down-1', 'down-0', 'down-2'], fps: 6 },
  walkLeft: { frames: ['left-0', 'left-1', 'left-0', 'left-2'], fps: 6 },
  walkRight: { frames: ['right-0', 'right-1', 'right-0', 'right-2'], fps: 6 },
  walkUp: { frames: ['up-0', 'up-1', 'up-0', 'up-2'], fps: 6 },
  attack: { frames: ['attack', 'f0'], fps: 6, loop: false },
};

const DEFAULT_BACK = { Z: '2', E: '2' };

/**
 * A creature that walks on the ground.
 *   s: { w, h, legTop, palette, down:[rows], side:[rows](facing LEFT),
 *        up:[rows]|null, backSub:{}, attack:[rows]|null, hurt:[rows]|null }
 */
function walker(name, s) {
  const w = s.w, h = s.h;
  const legTop = s.legTop != null ? s.legTop : Math.max(1, h - 4);
  const down = fit(s.down, w, h);
  const left = fit(s.side || s.down, w, h);
  const right = mirrorRows(left);
  const up = s.up ? fit(s.up, w, h) : sub(down, s.backSub || DEFAULT_BACK);
  const F = {};
  const mk = (dir, rows) => {
    F[dir + '-0'] = rows;
    F[dir + '-1'] = liftFoot(rows, legTop, 0);
    F[dir + '-2'] = liftFoot(rows, legTop, 1);
    F[dir + '-3'] = bob(rows, legTop);
  };
  mk('down', down); mk('left', left); mk('right', right); mk('up', up);
  F.attack = s.attack ? fit(s.attack, w, h) : rise(down, legTop);
  F.hurt = s.hurt ? fit(s.hurt, w, h) : flinch(down, legTop);
  F['attack-side'] = s.attackSide ? fit(s.attackSide, w, h) : rise(left, legTop);
  return push(name, { w, h, palette: s.palette, frames: F, anims: WALK_ANIMS });
}

/**
 * A creature that flies or hovers: same four facings, but the "step" frames are
 * a vertical bob instead of a foot lift. Also exposes f0/f1/f2 + a float anim.
 */
function hoverer(name, s) {
  const w = s.w, h = s.h;
  const down = fit(s.down, w, h);
  const left = fit(s.side || s.down, w, h);
  const right = mirrorRows(left);
  const up = s.up ? fit(s.up, w, h) : sub(down, s.backSub || DEFAULT_BACK);
  const F = {};
  const mk = (dir, rows) => {
    F[dir + '-0'] = rows;
    F[dir + '-1'] = shiftY(rows, -1);
    F[dir + '-2'] = rows;
    F[dir + '-3'] = shiftY(rows, 1);
  };
  mk('down', down); mk('left', left); mk('right', right); mk('up', up);
  F.f0 = down; F.f1 = shiftY(down, -1); F.f2 = shiftY(down, 1);
  F.attack = s.attack ? fit(s.attack, w, h) : shiftY(down, -1);
  F.hurt = s.hurt ? fit(s.hurt, w, h) : shiftX(down, 1);
  F['attack-side'] = shiftY(left, -1);
  return push(name, { w, h, palette: s.palette, frames: F, anims: FLOAT_ANIMS });
}

/**
 * An ooze / slime / incorporeal mass: one silhouette that pulses. Every
 * direction frame is filled in so nothing ever renders blank.
 */
function blob(name, s) {
  const w = s.w, h = s.h;
  const a = fit(s.body, w, h);
  const b = s.body2 ? fit(s.body2, w, h) : squash(a);
  const c = s.body3 ? fit(s.body3, w, h) : stretch(a);
  const F = { f0: a, f1: b, f2: c };
  const seq = [a, b, c, b];
  for (const d of ['down', 'left', 'right', 'up']) {
    for (let i = 0; i < 4; i++) F[`${d}-${i}`] = seq[i];
  }
  F.attack = s.attack ? fit(s.attack, w, h) : stretch(c);
  F.hurt = s.hurt ? fit(s.hurt, w, h) : shiftX(a, 1);
  F['attack-side'] = F.attack;
  return push(name, { w, h, palette: s.palette, frames: F, anims: FLOAT_ANIMS });
}

/** A thing that does not move on its own (mimic, animated statue, treasure). */
function still(name, s) {
  const w = s.w, h = s.h;
  const a = fit(s.body, w, h);
  const F = { f0: a, f1: a, f2: a };
  for (const d of ['down', 'left', 'right', 'up']) {
    for (let i = 0; i < 4; i++) F[`${d}-${i}`] = a;
  }
  F.attack = s.attack ? fit(s.attack, w, h) : stretch(a);
  F.hurt = s.hurt ? fit(s.hurt, w, h) : shiftX(a, 1);
  F['attack-side'] = F.attack;
  return push(name, { w, h, palette: s.palette, frames: F, anims: FLOAT_ANIMS });
}

// Authored families use five-tone material keys instead of the legacy numeric
// triples. Keep those keys (and unchanged materials) when applying a variant.
const SCULPT_VARIANT_RAMPS = {
  wolf: [['abcde', '2'], ['pqrst', '8']],
  goblin: [['abcde', '2'], ['fghij', '5'], ['klmno', '8']],
  orc: [['abcde', '2'], ['fghij', '5'], ['klmno', '8']],
  ogre: [['abcde', '2'], ['fghij', '5'], ['klmno', '8']],
  skeleton: [['pqrst', '2'], ['fghij', '5'], ['klmno', '8']],
};
const SCULPT_VARIANTS = new Set();

/** Same silhouette, new palette â€” resolved after all base art replacements. */
function variant(name, baseName, palette, extra) {
  const base = DEF_INDEX.get(baseName);
  if (!base) return name;
  if (SCULPT_VARIANT_RAMPS[baseName]) {
    SCULPT_VARIANTS.add(name);
    const recolored = { ...base.palette };
    for (const [keys, mid] of SCULPT_VARIANT_RAMPS[baseName]) {
      if (!palette[mid]) continue;
      const shades = ramp(palette[mid], 5);
      [...keys].forEach((key, i) => { if (key in base.palette) recolored[key] = shades[i]; });
    }
    // Eyes/hair remain identity details; do not replace the authored outline.
    for (const key of ['E', 'H']) if (key in base.palette && palette[key]) recolored[key] = palette[key];
    palette = recolored;
  }
  push(name, {
    w: base.w, h: base.h, palette,
    frames: extra ? Object.assign({}, base.frames, extra) : base.frames,
    anims: base.anims,
  });
  return name;
}

