export function registerMonsterSprites() {
  if (registered) return DEFS.length;
  registered = true;
  tinySprites();
  mediumSprites();
  largeSprites(); largeSprites2(); largeSprites3(); largeSprites4();
  hugeSprites(); hugeSprites2(); hugeSprites3(); hugeSprites4();
  colossalSprites(); colossalSprites2(); colossalSprites3();
  gapSprites(); gapSprites2(); gapSprites3();
  // Authored PixelForge silhouettes retain the bestiary's four-facing and
  // pose contract; the usual walk builder animates the finished source views.
  for (const [name, art, legTop] of [['goblin', GOBLIN, 18], ['orc', ORC, 25], ['ogre', OGRE, 33], ['skeleton', SKELETON, 21], ['wolf', WOLF, 17], ['dragon-young', WYRM, 39], ['dragon-adult', WYRM, 39]]) {
    const old=DEFS.findIndex(d=>d.name===name);
    if(old>=0)DEFS.splice(old,1);
    const palette=art===WYRM ? {...art.palette,a:'MAIN_D',b:'MAIN_D',c:'MAIN',d:'MAIN_L',e:'MAIN_L',k:'ALT_D',l:'ALT_D',m:'ALT',n:'ALT_L',o:'ALT_L'} : art.palette;
    walker(name, { w: art.w, h: art.h, palette, legTop,
      down: art.frames.down, side: art.frames.left, up: art.frames.up });
  }
  // Variants must inherit the final frame set, dimensions and material keys.
  // Building them earlier silently left dire wolves (and eight other variants)
  // on the old art even though their base families had been upgraded.
  variantSprites();
  for (const { name, def } of DEFS) defineSprite(name, def);
  return DEFS.length;
}

/** Every sprite family this module can draw, for debug/bestiary screens. */
export function monsterSpriteNames() {
  return DEFS.map((d) => d.name);
}

// ===========================================================================
// MONSTER_SPRITE_MAP â€” monster id -> { sprite, tint, tintAmt, scale }
//
// `tint` is a colour washed over the sprite by drawSprite(); it is how one
// silhouette covers a whole family (dire wolf, orog, every dragon colour).
// `scale` sizes a shared body up or down (wyrmling vs ancient, ogre vs giant).
// ===========================================================================

/** Chromatic + metallic dragon hues, applied to the neutral-grey dragon body. */
const DRAGON_TINTS = {
  red: '#c0281c', blue: '#2a6ad0', green: '#3f8a3a', black: '#33303c',
  white: '#c8e8f8', brass: '#c8a03a', bronze: '#9a6a24', copper: '#c06a3a',
  gold: '#e8c33a', silver: '#c0ccd8', shadow: '#4a3a5a', deep: '#2a4a8a',
};
const DRAGON_AGES = {
  wyrmling: { sprite: 'dragon-young', scale: 0.55 },
  young: { sprite: 'dragon-young', scale: 1 },
  adult: { sprite: 'dragon-adult', scale: 1 },
  ancient: { sprite: 'dragon-ancient', scale: 1 },
};

function buildDragonEntries() {
  const out = {};
  for (const [colour, tint] of Object.entries(DRAGON_TINTS)) {
    for (const [age, cfg] of Object.entries(DRAGON_AGES)) {
      const e = { sprite: cfg.sprite, tint, tintAmt: 0.62, scale: cfg.scale };
      out[`${age}-${colour}-dragon`] = e;      // "adult-red-dragon"
      out[`${colour}-dragon-${age}`] = e;      // "red-dragon-adult"
      out[`${colour}-${age}-dragon`] = e;      // "red-adult-dragon"
    }
    out[`${colour}-dragon`] = { sprite: 'dragon-adult', tint, tintAmt: 0.62, scale: 1 };
    out[`${colour}-dragon-wyrmling`] = { sprite: 'dragon-young', tint, tintAmt: 0.62, scale: 0.55 };
    out[`${colour}-drake`] = { sprite: 'wyvern', tint, tintAmt: 0.5, scale: 1 };
  }
  return out;
}

